"""xc -- keyed cross-channel coupling mark, DETECTOR ONLY. Experimental: not learned by any tested model.
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from ..prf import domain_id, prf_unit
from ._stats import loo_residual, robust_scale, winsorize


NAME = "xc"


def pairs(key: bytes, columns: list[str], k: int = 3, max_lag: int = 8):
    """k distinct ordered pairs (src, dst), lag in [1, max_lag], sign in {-1, +1}; pure function of the key."""
    cols = sorted(columns)
    n = len(cols)
    out, ctr, seen = [], 0, set()
    while len(out) < min(k, n * (n - 1)) and ctr < 1000:
        u = prf_unit(key, domain_id("xc:pair"), np.arange(4 * ctr, 4 * ctr + 4))
        ctr += 1
        i, j = int(u[0] * n), int(u[1] * n)
        if i == j or (i, j) in seen:
            continue
        seen.add((i, j))
        out.append({"src": cols[i], "dst": cols[j], "lag": 1 + int(u[2] * max_lag), "sign": 1 if u[3] < 0.5 else -1})
    return out


def _res(x):
    r = winsorize(loo_residual(np.where(np.isfinite(x), x, np.nanmedian(x))))
    s = robust_scale(r)
    return r / s if s > 0 else r, s


def _stat(df, key, params):
    tot = 0.0
    res = {c: _res(df[c].to_numpy(np.float64))[0] for c in params["columns"] if c in df.columns}
    for p in pairs(key, params["columns"], params["k"], params["max_lag"]):
        if p["src"] in res and p["dst"] in res:
            a, b, L = res[p["src"]], res[p["dst"]], p["lag"]
            tot += p["sign"] * float(np.corrcoef(a[:-L], b[L:])[0, 1])
    return tot


def detect(df: pd.DataFrame, key: bytes, params: dict, n_decoys: int = 200, **_):
    from ..decoys import decoy_keys
    s = _stat(df, key, params)
    d = np.array([_stat(df, k, params) for k in decoy_keys(n_decoys, 11)])
    return {"method": NAME, "stat": s, "z": float((s - d.mean()) / (d.std() + 1e-12)),
            "p": float((1 + np.sum(d >= s)) / (1 + n_decoys)), "p_floor": 1 / (1 + n_decoys)}
